export function scopedCases(s,f={}){return s.cases.filter(c=>(!f.year||c.year===f.year)&&(!f.route||c.route===f.route)&&(!f.prodi||c.prodi===f.prodi)&&(!f.region||c.region===f.region)&&(!f.status||c.status===f.status)&&(!f.search||`${c.name} ${c.id} ${c.prodi}`.toLowerCase().includes(f.search.toLowerCase())));}
export function metrics(cases){const accepted=cases.filter(c=>['Diterima','Daftar ulang selesai','Aktif'].includes(c.source)).length;const registered=cases.filter(c=>['Daftar ulang selesai','Aktif'].includes(c.source)).length;return {total:cases.length,accepted,registered,active:cases.filter(c=>c.source==='Aktif').length,final:cases.filter(c=>['Diterima','Ditolak','Daftar ulang selesai','Aktif'].includes(c.source)).length};}
export function audit(s,actor,entity,action,before='',after=''){s.audit.unshift({id:crypto.randomUUID(),actor,entity,action,before,after,time:s.now});}
export function transition(s,id,next,actor,reason=''){const c=s.cases.find(x=>x.id===id);if(!c)throw Error('Pendaftaran tidak ditemukan.');if(actor!=='Petugas'&&!['Menunggu verifikasi'].includes(next))throw Error('Tindakan memerlukan petugas.');if(actor==='Calon mahasiswa'&&!['Perlu tindakan','Perlu perbaikan'].includes(c.status))throw Error('Tugas belum dapat dikirim.');if(next==='Selesai'&&c.status!=='Menunggu verifikasi')throw Error('Periksa pengajuan terlebih dahulu.');if(next==='Perlu perbaikan'&&!reason.trim())throw Error('Tuliskan alasan perbaikan.');const before=c.status;c.status=next;c.reason=reason;if(next==='Selesai'){c.source=c.stage===3?'Aktif':'Daftar ulang selesai';}if(['Selesai','Menunggu verifikasi'].includes(next))s.reminders.filter(r=>r.caseId===id&&r.status==='Dijadwalkan').forEach(r=>r.status='Dibatalkan');audit(s,actor,id,'Perubahan tugas',before,next);return c;}
export function reminderEligibility(s,c){if(!c)return 'Pendaftaran tidak ditemukan';if(!['Perlu tindakan','Perlu perbaikan'].includes(c.status))return 'Tugas tidak memerlukan tindakan calon mahasiswa';if(c.source!=='Diterima')return 'Status penerimaan belum relevan';if(!c.deadline)return 'Jadwal belum diumumkan';if(new Date(s.now)>=new Date(c.deadline))return 'Tenggat sudah terlewati';if(new Date(s.now)-new Date(s.updatedAt)>86400000)return 'Data perlu diperbarui';if(s.tickets.some(t=>t.caseId===c.id&&t.status!=='Selesai'))return 'Terdapat tiket bantuan yang sedang ditangani';const local=new Date(new Date(s.now).getTime()+7*3600000);if(local.getUTCHours()<7||local.getUTCHours()>=20)return 'Sedang dalam jam tenang (20.00–07.00 WIB)';if(s.reminders.some(r=>r.caseId===c.id&&new Date(new Date(r.time).getTime()+7*3600000).toISOString().slice(0,10)===local.toISOString().slice(0,10)&&r.status==='Simulasi'))return 'Batas satu pengingat per hari telah tercapai';return null;}
export function simulateReminder(s,id){const c=s.cases.find(x=>x.id===id);const blocked=reminderEligibility(s,c);const r={id:crypto.randomUUID(),caseId:id,time:s.now,status:blocked?'Ditahan':'Simulasi',reason:blocked||'Pratinjau di portal. Tidak ada pesan eksternal yang dikirim.',obligations:c?.requirements?.filter(r=>r.applicable&&['Perlu tindakan','Perlu perbaikan'].includes(r.status)).map(r=>r.name)||['Berkas daftar ulang']};s.reminders.unshift(r);audit(s,'Petugas',id,'Pengingat '+r.status);return r;}
export function book(s,sessionId,caseId){const session=s.sessions.find(x=>x.id===sessionId);if(!session||session.status!=='Terjadwal'||new Date(session.date)<=new Date(s.now))throw Error('Sesi sudah tidak dapat dipesan.');if(session.bookings.includes(caseId))throw Error('Kamu sudah terdaftar pada sesi ini.');if(session.bookings.length>=session.capacity)throw Error('Slot sesi sudah penuh.');session.bookings.push(caseId);audit(s,'Calon mahasiswa',sessionId,'Pemesanan sesi',null,caseId);}
export function cancelBooking(s,sessionId,caseId){const session=s.sessions.find(x=>x.id===sessionId);if(!session)throw Error('Sesi tidak ditemukan.');session.bookings=session.bookings.filter(x=>x!==caseId);audit(s,'Calon mahasiswa',sessionId,'Pembatalan pemesanan');}
export function scenarioResult(a){if(!Number.isFinite(a.count)||a.count<0||a.count>10000000||!['accepted','registered','active'].every(k=>Number.isFinite(a[k])&&a[k]>=0&&a[k]<=100))throw Error('Jumlah harus 0–10.000.000 dan proporsi 0–100%.');return Math.round(a.count*a.accepted/100*a.registered/100*a.active/100);}
export function parseCSV(text){const src=text.replace(/^\uFEFF/,'');const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<src.length;i++){const ch=src[i];if(ch==='"'){if(quoted&&src[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(ch===';'&&!quoted){row.push(cell);cell='';}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&src[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell='';}else cell+=ch;}if(quoted)throw Error('Tanda kutip CSV belum ditutup.');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);if(rows.length<2)throw Error('CSV harus berisi judul kolom dan data.');const headers=rows.shift().map(x=>x.trim());if(new Set(headers).size!==headers.length)throw Error('Nama kolom ganda.');return rows.map((r,i)=>{if(r.length!==headers.length)throw Error(`Jumlah kolom tidak sesuai pada baris ${i+2}.`);return Object.fromEntries(headers.map((h,j)=>[h,r[j].trim()]));});}
export function validateImport(rows){const required=['ID_Pendaftaran','Nama','Kode_Prodi','Tahun_Penerimaan','Wilayah','Status'];const issues=[],seen=new Set();const allowed=['Mendaftar','Hasil belum diumumkan','Diterima','Ditolak','Daftar ulang selesai','Aktif'];rows.forEach((r,i)=>{required.forEach(k=>{if(!r[k])issues.push(`Baris ${i+2}: ${k} wajib diisi.`);});if(seen.has(r.ID_Pendaftaran))issues.push(`Baris ${i+2}: ID ${r.ID_Pendaftaran} berulang; publikasi ditahan.`);seen.add(r.ID_Pendaftaran);if(!allowed.includes(r.Status))issues.push(`Baris ${i+2}: status tidak dikenali.`);if(!/^20\d{2}$/.test(r.Tahun_Penerimaan||''))issues.push(`Baris ${i+2}: tahun tidak valid.`);});return issues;}
